#if 0
"""
import sys

def fib(n):
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a

if __name__ == "__main__":
    if len(sys.argv) != 2:
        sys.exit(1)
    try:
        n = int(sys.argv[1])
    except ValueError:
        sys.exit(1)
    print(fib(n))
"""
#endif
#include <stdio.h>
#include <stdlib.h>

long long fib(int n) {
    long long a = 0, b = 1, t;
    for (int i = 0; i < n; ++i) {
        t = a + b;
        a = b;
        b = t;
    }
    return a;
}

int main(int argc, char *argv[]) {
    if (argc != 2) return 1;
    int n = atoi(argv[1]);
    printf("%lld\n", fib(n));
    return 0;
}
EOF

